//! The shared conformance vectors (vectors/t32-vectors.json), generated by the
//! exact-arithmetic oracle in tools/oracle.py. Every other implementation can
//! run the same file.

use serde_json::Value;
use t32::{Duration, Error, Instant, Stamp, UtcDateTime};

fn vectors() -> Value {
    serde_json::from_str(include_str!("../../vectors/t32-vectors.json")).unwrap()
}

fn code(e: Error) -> &'static str {
    match e {
        Error::Empty => "empty",
        Error::TooLong => "too_long",
        Error::InvalidChar(_) => "invalid_char",
        Error::MisplacedHyphen => "misplaced_hyphen",
        Error::MissingSign => "missing_sign",
        Error::RemovedTime => "removed_time",
        Error::NotALeapSecond => "not_a_leap_second",
        Error::InvalidDateTime => "invalid_date",
        Error::OutOfRange => "out_of_range",
        Error::InvalidLength(_) => "invalid_length",
        _ => "other",
    }
}

fn outcome<T: ToString>(r: Result<T, Error>) -> (Option<String>, Option<&'static str>) {
    match r {
        Ok(v) => (Some(v.to_string()), None),
        Err(e) => (None, Some(code(e))),
    }
}

fn expected(row: &Value, field: &str) -> (Option<String>, Option<&'static str>) {
    match row.get("error").and_then(Value::as_str) {
        Some(e) => (None, Some(Box::leak(e.to_owned().into_boxed_str()))),
        None => (Some(row[field].as_str().unwrap().to_owned()), None),
    }
}

fn int(row: &Value, field: &str) -> i128 {
    row[field].as_str().unwrap().parse().unwrap()
}

#[test]
fn parse() {
    for row in vectors()["parse"].as_array().unwrap() {
        let input = row["input"].as_str().unwrap();
        assert_eq!(
            outcome(input.parse::<Stamp>()),
            expected(row, "stamp"),
            "{input:?}"
        );
    }
}

#[test]
fn encode_utc() {
    for row in vectors()["encode_utc"].as_array().unwrap() {
        let utc = row["utc"].as_str().unwrap();
        let len = row["length"].as_u64().unwrap() as u8;
        let label = utc.parse::<UtcDateTime>();
        let got = label
            .and_then(Instant::from_utc)
            .and_then(|t| Stamp::new(t, len));
        assert_eq!(outcome(got), expected(row, "stamp"), "{utc} at {len}");
        if let Some(p) = row.get("provisional") {
            assert_eq!(
                label.unwrap().is_provisional(),
                p.as_bool().unwrap(),
                "{utc}"
            );
        }
    }
}

#[test]
fn encode_unix() {
    for row in vectors()["encode_unix"].as_array().unwrap() {
        let n = int(row, "unix_nanos");
        let len = row["length"].as_u64().unwrap() as u8;
        let instant = Instant::from_unix_nanos(n);
        let got = instant.and_then(|t| Stamp::new(t, len));
        assert_eq!(outcome(got), expected(row, "stamp"), "{n}");
        if let Some(p) = row.get("provisional") {
            assert_eq!(
                instant.unwrap().is_provisional(),
                p.as_bool().unwrap(),
                "{n}"
            );
        }
    }
}

#[test]
fn encode_tai() {
    for row in vectors()["encode_tai"].as_array().unwrap() {
        let units: u128 = row["units"].as_str().unwrap().parse().unwrap();
        let len = row["length"].as_u64().unwrap() as u8;
        let got = Instant::from_units(units).and_then(|t| Stamp::new(t, len));
        assert_eq!(outcome(got), expected(row, "stamp"), "{units} at {len}");
    }
}

#[test]
fn utc_errors() {
    for row in vectors()["utc_errors"].as_array().unwrap() {
        let utc = row["utc"].as_str().unwrap();
        let got = utc.parse::<UtcDateTime>().and_then(Instant::from_utc);
        assert_eq!(got.map_err(code).err(), row["error"].as_str(), "{utc}");
    }
}

#[test]
fn decode() {
    for row in vectors()["decode"].as_array().unwrap() {
        let s: Stamp = row["stamp"].as_str().unwrap().parse().unwrap();
        assert_eq!(s.start().units() as i128, int(row, "start_units"), "{s}");
        assert_eq!(
            s.start().to_utc().to_string(),
            row["start_utc"].as_str().unwrap(),
            "{s} start"
        );
        assert_eq!(
            s.start().in_inserted_time(),
            row["start_inserted"].as_bool().unwrap(),
            "{s}"
        );
        assert_eq!(
            s.start().is_provisional(),
            row["start_provisional"].as_bool().unwrap(),
            "{s}"
        );
        match s.end() {
            None => assert!(row["end_utc"].is_null(), "{s}"),
            Some(end) => {
                assert_eq!(
                    end.to_utc().to_string(),
                    row["end_utc"].as_str().unwrap(),
                    "{s} end"
                );
                assert_eq!(
                    end.in_inserted_time(),
                    row["end_inserted"].as_bool().unwrap(),
                    "{s}"
                );
                assert_eq!(
                    end.is_provisional(),
                    row["end_provisional"].as_bool().unwrap(),
                    "{s}"
                );
            }
        }
    }
}

#[test]
fn durations() {
    for row in vectors()["durations"].as_array().unwrap() {
        let Some(text) = row["text"].as_str() else {
            // From nanoseconds, out of range.
            let got = Duration::from_nanos(int(row, "nanos"));
            assert_eq!(got.map_err(code).err(), row["error"].as_str(), "{row}");
            continue;
        };
        if let Some(e) = row.get("error") {
            assert_eq!(
                text.parse::<Duration>().map_err(code).err(),
                e.as_str(),
                "{text:?}"
            );
        } else if let Some(canonical) = row.get("canonical") {
            assert_eq!(
                text.parse::<Duration>().unwrap().to_string(),
                canonical.as_str().unwrap()
            );
        } else {
            let units = int(row, "units");
            let d = Duration::from_units(units).unwrap();
            assert_eq!(d.to_string(), text);
            assert_eq!(text.parse::<Duration>().unwrap(), d);
            if row.get("nanos").is_some() {
                assert_eq!(Duration::from_nanos(int(row, "nanos")).unwrap(), d);
            }
        }
    }
}

fn stamp(row: &Value, field: &str) -> Stamp {
    row[field].as_str().unwrap().parse().unwrap()
}

#[test]
fn binary() {
    for row in vectors()["binary"].as_array().unwrap() {
        let s = stamp(row, "stamp");
        let bytes = (5 * usize::from(s.len())).div_ceil(8);
        assert_eq!(
            format!("{:0w$x}", s.value(), w = 2 * bytes),
            row["bytes"].as_str().unwrap(),
            "{s}"
        );
    }
}

#[test]
fn upper_bound() {
    for row in vectors()["upper_bound"].as_array().unwrap() {
        let bound = stamp(row, "prefix").upper_bound().map(|b| b.to_string());
        assert_eq!(bound.as_deref(), row["bound"].as_str(), "{row}");
    }
}

#[test]
fn max_length() {
    for row in vectors()["max_length"].as_array().unwrap() {
        let r = Duration::from_units(int(row, "units")).unwrap();
        assert_eq!(
            u64::from(Stamp::max_len(r)),
            row["length"].as_u64().unwrap(),
            "{row}"
        );
    }
}

#[test]
fn add() {
    for row in vectors()["add"].as_array().unwrap() {
        let d: Duration = row["duration"].as_str().unwrap().parse().unwrap();
        let got = stamp(row, "stamp").checked_add(d);
        assert_eq!(outcome(got), expected(row, "result"), "{row}");
    }
}

#[test]
fn difference() {
    for row in vectors()["difference"].as_array().unwrap() {
        let (a, b) = (stamp(row, "a"), stamp(row, "b"));
        assert_eq!(
            (b.start() - a.start()).to_string(),
            row["b_minus_a"].as_str().unwrap(),
            "{row}"
        );
    }
}
